    IF NEW.status NOT IN ('pending','in_transit','delivered','returned') THEN
        RAISE EXCEPTION 'Estado de envío inválido';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        NEW.updated_at = CURRENT_TIMESTAMP;
